    /** @return array{he: string, en: string, ru: string, fr: string}|null */
    public static function labels(string $key): ?array
    {
        return self::LABELS[$key] ?? null;
    }

    public static function label(string $key, string $locale): ?string
    {
        if (! in_array($locale, ['he', 'en', 'ru', 'fr'], true)) {
            return null;
        }

        return self::LABELS[$key][$locale] ?? null;
    }

    /** @return list<string> */
    public static function keys(): array
    {
        return array_keys(self::LABELS);
    }
